pub fn spiral(m: List[List[Int]]) -> List[Int] {
    var out: List[Int] = []
    if m.len() == 0 {
        return out
    }
    var top = 0
    var bottom = m.len() - 1
    var left = 0
    var right = row_len(m: m) - 1

    while top <= bottom and left <= right {
        var c = left
        while c <= right {
            out = out.push(cell(m: m, r: top, c: c))
            c = c + 1
        }
        top = top + 1

        var r = top
        while r <= bottom {
            out = out.push(cell(m: m, r: r, c: right))
            r = r + 1
        }
        right = right - 1

        if top <= bottom {
            c = right
            while c >= left {
                out = out.push(cell(m: m, r: bottom, c: c))
                c = c - 1
            }
            bottom = bottom - 1
        }

        if left <= right {
            r = bottom
            while r >= top {
                out = out.push(cell(m: m, r: r, c: left))
                r = r - 1
            }
            left = left + 1
        }
    }
    return out
}
